quartzdice.css:
html[data-theme=dark].bgaext_dark .crystal {
  filter: var(--highlight-min);
}
html[data-theme=dark].bgaext_dark .quartz-table .quartz-mining-cart .quartz-mining-cart-title span {
  background-color: var(--dark-20);
}
html[data-theme=dark].bgaext_dark .quartz-dice-stock-content .quartz-dice-stock-block {
  border: 2px solid var(--blue-70);
}
html[data-theme=dark].bgaext_dark .quartz-dice-stock-content .quartz-dice-stock-block .quartz-dice-stock-block-icon {
  background: var(--blue-70);
}
html[data-theme=dark].bgaext_dark .quartz-select-crystal input {
  border: 1px solid var(--light-50);
}
html[data-theme=dark].bgaext_dark .quartz-perform-action-box .quartz-perform-action-dices .quartz-perform-action-dice.selected {
  outline-color: var(--blue-80);
  outline-width: 3px;
}

summy.css:
html[data-theme=dark].bgaext_bright .bga-cards_card-side {
  filter: var(--ext-bright);
}
html[data-theme=dark].bgaext_dark [style="background-color: bisque;"] {
  background-color: #663800 !important;
}
html[data-theme=dark].bgaext_dark .sum-token {
  border-color: #663800;
}
html[data-theme=dark].bgaext_dark .card-stock.deck[data-empty=true] {
  background: var(--dark-back);
}
